const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const M = data[1];
const S = data[2];

function digitSum(x) {
    let sum = 0;
    while (x > 0) {
        sum += x % 10;
        x = Math.floor(x / 10);
    }
    return sum;
}

for (let i = M; i >= N; i--) {
    if (digitSum(i) === S) {
        console.log(i);
        process.exit(0);
    }
}

console.log(-1);
